import java.util.*;

public class Main {
    static class GreetingService {
        String message(String prefix, String name) {
            return prefix + ", " + name.trim();
        }
    }

    static String resolve(String profileValue, String commonValue) {
        if (!profileValue.equals("-")) return profileValue;
        if (!commonValue.equals("-")) return commonValue;
        return "Hello";
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String profile = sc.nextLine();
        String profileValue = sc.nextLine();
        String commonValue = sc.nextLine();
        String name = sc.nextLine();
        if (name.isBlank()) {
            System.out.println("400 NAME_REQUIRED");
        } else {
            GreetingService service = new GreetingService();
            String message = service.message(resolve(profileValue, commonValue), name);
            System.out.println("200 [" + profile + "] " + message);
        }
    }
}

