import java.util.*;

public class Main {
    static String route(String api, boolean confirmed) {
        if (api.equals("JAKARTA_REST") || api.equals("CDI")) return "NATIVE_QUARKUS_API";
        Set<String> springApis = Set.of("SPRING_DI", "SPRING_WEB", "SPRING_DATA", "SPRING_SECURITY");
        if (springApis.contains(api)) {
            return confirmed ? "COMPATIBILITY_EXTENSION:TEST_SUBSET" : "SPIKE:CHECK_SUPPORTED_SUBSET";
        }
        return "REWRITE_REQUIRED:UNSUPPORTED_API";
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String api = sc.nextLine();
        boolean confirmed = Boolean.parseBoolean(sc.nextLine());
        System.out.println(route(api, confirmed));
    }
}

